// --- Hash-based view routing ---
function routeViews(){
  var hash = (location.hash || '#ana').replace('#','');
  var home = document.getElementById('home-view');
  var legalViews = document.querySelectorAll('.legal');
  legalViews.forEach(function(v){ v.classList.remove('active'); });
  if(hash === 'aydinlatma-metni'){
    home.classList.add('hidden');
    document.getElementById('view-aydinlatma-metni').classList.add('active');
    window.scrollTo(0,0);
  } else if(hash === 'cerez-politikasi'){
    home.classList.add('hidden');
    document.getElementById('view-cerez-politikasi').classList.add('active');
    window.scrollTo(0,0);
  } else {
    home.classList.remove('hidden');
  }
}
window.addEventListener('hashchange', routeViews);
routeViews();

// --- Cookie consent (per-viewer, local only) ---
try{
  if(!localStorage.getItem('rasyoapp_cookie_consent')){
    document.getElementById('cookieBar').classList.add('show');
  }
}catch(e){}
document.getElementById('cookieAccept').addEventListener('click', function(){
  try{ localStorage.setItem('rasyoapp_cookie_consent','1'); }catch(e){}
  document.getElementById('cookieBar').classList.remove('show');
});

// --- 3D hero: rotating key-like wireframe construct ---
(function(){
  var canvas = document.getElementById('heroCanvas');
  if(!canvas || typeof THREE === 'undefined') return;
  var renderer = new THREE.WebGLRenderer({canvas:canvas, alpha:true, antialias:true});
  var scene = new THREE.Scene();
  var camera = new THREE.PerspectiveCamera(45, 1, 0.1, 100);
  camera.position.set(0,0,6);

  var group = new THREE.Group();
  var ring = new THREE.Mesh(
    new THREE.TorusGeometry(1.2, 0.08, 16, 64),
    new THREE.MeshBasicMaterial({color:0xC9A44C, wireframe:true})
  );
  group.add(ring);

  var shaft = new THREE.Mesh(
    new THREE.CylinderGeometry(0.1,0.1,1.6,12),
    new THREE.MeshBasicMaterial({color:0x3FA8A0, wireframe:true})
  );
  shaft.rotation.z = Math.PI/2;
  shaft.position.x = 1.6;
  group.add(shaft);

  var teeth = new THREE.Mesh(
    new THREE.BoxGeometry(0.5,0.18,0.18),
    new THREE.MeshBasicMaterial({color:0x3FA8A0, wireframe:true})
  );
  teeth.position.set(2.5,0.15,0);
  group.add(teeth);
  var teeth2 = teeth.clone(); teeth2.position.set(2.8,-0.2,0); group.add(teeth2);

  var core = new THREE.Mesh(
    new THREE.IcosahedronGeometry(0.55,0),
    new THREE.MeshBasicMaterial({color:0xE8E6DE, wireframe:true, transparent:true, opacity:0.5})
  );
  group.add(core);

  scene.add(group);

  function resize(){
    var w = canvas.clientWidth, h = canvas.clientHeight || w;
    renderer.setSize(w,h,false);
    camera.aspect = w/h; camera.updateProjectionMatrix();
  }
  window.addEventListener('resize', resize);
  resize();

  function animate(){
    group.rotation.y += 0.006;
    group.rotation.x = Math.sin(Date.now()*0.0004)*0.25;
    core.rotation.y -= 0.012;
    renderer.render(scene, camera);
    requestAnimationFrame(animate);
  }
  animate();
})();

(function(){
  var canvas = document.getElementById('bgCanvas');
  if(!canvas || typeof THREE === 'undefined') return;
  var renderer = new THREE.WebGLRenderer({canvas:canvas, alpha:true, antialias:false});
  var scene = new THREE.Scene();
  var camera = new THREE.PerspectiveCamera(50, window.innerWidth/window.innerHeight, 0.1, 100);
  camera.position.z = 14;
  var count = 220;
  var positions = new Float32Array(count*3);
  for(var i=0;i<count;i++){
    positions[i*3] = (Math.random()-0.5)*28;
    positions[i*3+1] = (Math.random()-0.5)*20;
    positions[i*3+2] = (Math.random()-0.5)*16;
  }
  var geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(positions,3));
  var mat = new THREE.PointsMaterial({color:0xC9A44C, size:0.05, transparent:true, opacity:0.55});
  var points = new THREE.Points(geo, mat);
  scene.add(points);
  var lineMesh = new THREE.Mesh(new THREE.IcosahedronGeometry(5,1), new THREE.MeshBasicMaterial({color:0x3FA8A0, wireframe:true, transparent:true, opacity:0.08}));
  lineMesh.position.set(6,-2,-6);
  scene.add(lineMesh);
  function resize(){
    renderer.setSize(window.innerWidth, window.innerHeight, false);
    camera.aspect = window.innerWidth/window.innerHeight;
    camera.updateProjectionMatrix();
  }
  window.addEventListener('resize', resize);
  resize();
  function animate(){
    points.rotation.y += 0.0007;
    points.rotation.x += 0.0002;
    lineMesh.rotation.y += 0.0015;
    lineMesh.rotation.x += 0.001;
    renderer.render(scene, camera);
    requestAnimationFrame(animate);
  }
  animate();
})();

function makeMiniShape(id, geometry, color){
  var canvas = document.getElementById(id);
  if(!canvas || typeof THREE === 'undefined') return;
  var renderer = new THREE.WebGLRenderer({canvas:canvas, alpha:true, antialias:true});
  var scene = new THREE.Scene();
  var camera = new THREE.PerspectiveCamera(45,1,0.1,10);
  camera.position.z = 2.6;
  var mesh = new THREE.Mesh(geometry, new THREE.MeshBasicMaterial({color:color, wireframe:true}));
  scene.add(mesh);
  function resize(){
    var s = canvas.clientWidth || 60;
    renderer.setSize(s,s,false);
    camera.aspect = 1; camera.updateProjectionMatrix();
  }
  window.addEventListener('resize', resize);
  resize();
  (function animate(){
    mesh.rotation.y += 0.012;
    mesh.rotation.x += 0.007;
    renderer.render(scene, camera);
    requestAnimationFrame(animate);
  })();
}
if(typeof THREE !== 'undefined'){
  makeMiniShape('feat1Canvas', new THREE.IcosahedronGeometry(0.9,0), 0xC9A44C);
  makeMiniShape('feat2Canvas', new THREE.TorusKnotGeometry(0.6,0.18,80,8), 0x3FA8A0);
  makeMiniShape('feat3Canvas', new THREE.OctahedronGeometry(0.95,0), 0xE8E6DE);
  makeMiniShape('downloadCanvas', new THREE.TorusGeometry(0.75,0.22,16,48), 0xC9A44C);
}

(function(){
  var canvas = document.getElementById('matrixHero');
  if(!canvas) return;
  var ctx = canvas.getContext('2d');
  var chars = '01ABCDEF0123456789'.split('');
  var fontSize = 13;
  var columns, drops;
  function setup(){
    var w = canvas.clientWidth || 300, h = canvas.clientHeight || w;
    canvas.width = w; canvas.height = h;
    columns = Math.max(1, Math.ceil(w / fontSize));
    drops = new Array(columns).fill(0).map(function(){ return Math.random()*(h/fontSize); });
  }
  window.addEventListener('resize', setup);
  setup();
  var lastTick = 0;
  var stepInterval = 45;
  function draw(ts){
    requestAnimationFrame(draw);
    if(ts - lastTick < stepInterval) return;
    lastTick = ts;
    ctx.fillStyle = 'rgba(13,19,33,0.10)';
    ctx.fillRect(0,0,canvas.width,canvas.height);
    ctx.font = fontSize + 'px monospace';
    for(var i=0;i<columns;i++){
      var text = chars[Math.floor(Math.random()*chars.length)];
      var y = drops[i]*fontSize;
      ctx.fillStyle = Math.random()>0.1 ? '#39E07A' : '#D7FFE4';
      ctx.fillText(text, i*fontSize, y);
      if(y > canvas.height && Math.random() > 0.975){ drops[i] = 0; }
      drops[i]++;
    }
  }
  requestAnimationFrame(draw);
})();

(function(){
  var items = document.querySelectorAll('.reveal');
  if(!('IntersectionObserver' in window)){
    items.forEach(function(el){ el.classList.add('in'); });
    return;
  }
  var obs = new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      if(entry.isIntersecting){ entry.target.classList.add('in'); obs.unobserve(entry.target); }
    });
  }, {threshold:0.15});
  items.forEach(function(el){ obs.observe(el); });
})();
var RASYOAPP_EXE_B64 = "";
(function(){
  var btn = document.getElementById('downloadBtn');
  if(!btn) return;
  btn.addEventListener('click', function(e){
    e.preventDefault();
    var byteChars = atob(RASYOAPP_EXE_B64);
    var byteNumbers = new Array(byteChars.length);
    for (var i = 0; i < byteChars.length; i++) { byteNumbers[i] = byteChars.charCodeAt(i); }
    var byteArray = new Uint8Array(byteNumbers);
    var blob = new Blob([byteArray], {type: 'application/octet-stream'});
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = 'RasyoApp.exe';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(function(){ URL.revokeObjectURL(url); }, 2000);
  });
})();